export function qualifiesForFreeShipping(subtotalCents) {
  return subtotalCents >= 5000;
}
export function discountCents(subtotalCents) {
  return subtotalCents >= 10000 ? 500 : 0;
}
import test from 'node:test';
import assert from 'node:assert/strict';
import { qualifiesForFreeShipping } from '../src/shipping.js';

test('free shipping starts at 5,000 cents', () => {
  assert.equal(qualifiesForFreeShipping(0), false);
  assert.equal(qualifiesForFreeShipping(4999), false);
  assert.equal(qualifiesForFreeShipping(5000), true);
  assert.equal(qualifiesForFreeShipping(5001), true);
});
import test from 'node:test';
import assert from 'node:assert/strict';
import { discountCents } from '../src/discount.js';

test('the 500-cent discount starts at 10,000 cents', () => {
  assert.equal(discountCents(0), 0);
  assert.equal(discountCents(9999), 0);
  assert.equal(discountCents(10000), 500);
  assert.equal(discountCents(10001), 500);
  assert.equal(discountCents(20000), 500);
});
